import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.CCCdsIgc.js";const _=JSON.parse('{"title":"翻译、截图与快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shortcuts.md","filePath":"guide/shortcuts.md"}'),o={name:"guide/shortcuts.md"};function l(i,t,c,n,h,s){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="翻译、截图与快捷键" tabindex="-1">翻译、截图与快捷键 <a class="header-anchor" href="#翻译、截图与快捷键" aria-label="Permalink to &quot;翻译、截图与快捷键&quot;">​</a></h1><h2 id="划词翻译" tabindex="-1">划词翻译 <a class="header-anchor" href="#划词翻译" aria-label="Permalink to &quot;划词翻译&quot;">​</a></h2><p>在<strong>任何程序</strong>里选中一段文字，按 <code>Ctrl + Alt + T</code>，鼠标旁边弹出译文：</p><ul><li>默认译成界面语言；原文已经是界面语言时，自动译成中文或越南语；</li><li>可以改原文重译、复制，或转到主窗口继续。</li></ul><h2 id="截图提问" tabindex="-1">截图提问 <a class="header-anchor" href="#截图提问" aria-label="Permalink to &quot;截图提问&quot;">​</a></h2><p>按 <code>Ctrl + Alt + S</code>（或右键悬浮球「截图提问」），框选屏幕上的一块，作为附件开一个新对话直接问。</p><h2 id="资源管理器右键菜单" tabindex="-1">资源管理器右键菜单 <a class="header-anchor" href="#资源管理器右键菜单" aria-label="Permalink to &quot;资源管理器右键菜单&quot;">​</a></h2><ul><li>在文件上右键：「发给 FlyknitBuddy 提问 / 总结 / 翻译」，多选的几个文件进同一个对话；</li><li>在文件夹上右键：「在这里用 FlyknitBuddy 办事」。</li></ul><p>Windows 11 在「显示更多选项」里。</p><h2 id="常用快捷键" tabindex="-1">常用快捷键 <a class="header-anchor" href="#常用快捷键" aria-label="Permalink to &quot;常用快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl + Alt + Space</code></td><td>打开 / 收起主窗口</td></tr><tr><td><code>Ctrl + Alt + T</code></td><td>划词翻译</td></tr><tr><td><code>Ctrl + Alt + S</code></td><td>截图提问</td></tr><tr><td><code>Ctrl + N</code></td><td>新建任务</td></tr><tr><td><code>Ctrl + ;</code></td><td>顺便问一句</td></tr><tr><td><code>Enter</code> / <code>Shift + Enter</code></td><td>发送 / 换行</td></tr></tbody></table><p>所有快捷键都能在「设置 → 快捷键」里改，冲突时会提示被谁占用。</p>',12)])])}const p=e(o,[["render",l]]);export{_ as __pageData,p as default};
